/* Public VK photo CDN URLs are generated by media-upload.html and placed here. */
window.VK_MEDIA = window.VK_MEDIA || {};
window.vkMediaUrl = window.vkMediaUrl || function (repo, path) {
    if (!path || /^(https?:|data:|blob:)/i.test(path)) return path;
    return window.VK_MEDIA[repo + "/" + path] || path;
};
